  const cells = game.ships.flatMap((s) => s.cells);
  assert.equal(new Set(cells.map(key)).size, 17);
  for (const [r, c] of cells) {
    assert.ok(r >= 0 && r <= 9 && c >= 0 && c <= 9, `off board: ${r},${c}`);
  }
});
